sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below



    var evalBulk = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    evalBulk.addParam('sysparm_name', 'disableAmendOutcome');
    evalBulk.addParam('sysparm_bulkID', g_form.getUniqueValue());
    evalBulk.getXMLAnswer(amendEval);
    //to restrict evaluation only for amend

    function amendEval(amendAnswer) {
        if (amendAnswer == 'true') { //atleast one of the bulk outcome has amend 

            setTimer = setTimeout(setTimerDelay, 2000);
            function setTimerDelay() {
                g_form.removeOption('outcome', 'Amend Trade', 'Amend Trade');
                g_form.addOption('outcome', 'Perform(ed) a trade repair / amendment in GHSS', 'Perform(ed) a trade repair / amendment in GHSS');
            }

        }
    }


}
